    56
    57  class KArchiveDirectoryPrivate
    58  {
    59  public:
    60      KArchiveDirectoryPrivate(KArchiveDirectory *parent) : q(parent)
    61      {
    62      }
    63
    64      ~KArchiveDirectoryPrivate()
    65      {
    66          qDeleteAll(entries);
    67      }
    68
    69      KArchiveDirectoryPrivate(const KArchiveDirectoryPrivate &) = delete;
    70      KArchiveDirectoryPrivate &operator=(const KArchiveDirectoryPrivate &) = delete;
    71
    72      static KArchiveDirectoryPrivate *get(KArchiveDirectory *directory)
    73      {
    74          return directory->d;
    75      }
    76
    77      // Returns in containingDirectory the directory that actually contains the returned entry
    78      const KArchiveEntry *entry(const QString &_name, KArchiveDirectory **containingDirectory) const
    79      {
    80          *containingDirectory = q;
    81
    82          QString name = QDir::cleanPath(_name);
    83          int pos = name.indexOf(QLatin1Char('/'));
    84          if (pos == 0) { // ouch absolute path (see also KArchive::findOrCreate)
    85              if (name.length() > 1) {
    86                  name = name.mid(1);   // remove leading slash
    87                  pos = name.indexOf(QLatin1Char('/'));   // look again
    88              } else { // "/"
    89                  return q;
    90              }
    91          }
    92          // trailing slash ? -> remove
    93          if (pos != -1 && pos == name.length() - 1) {
    94              name = name.left(pos);
    95              pos = name.indexOf(QLatin1Char('/'));   // look again
    96          }
    97          if (pos != -1) {
    98              const QString left = name.left(pos);
    99              const QString right = name.mid(pos + 1);
   100
   101              //qCDebug(KArchiveLog) << "left=" << left << "right=" << right;
   102
   103              KArchiveEntry *e = entries.value(left);
   104              if (!e || !e->isDirectory()) {
   105                  return nullptr;
   106              }
   107              *containingDirectory = static_cast<KArchiveDirectory *>(e);
   108              return (*containingDirectory)->d->entry(right, containingDirectory);
   109          }
   110
   111          return entries.value(name);
   112      }
   113
   114      KArchiveDirectory *q;
   115      QHash<QString, KArchiveEntry *> entries;
   116  };
