   122  KArchive::KArchive(const QString &fileName)
   123      : d(new KArchivePrivate(this))
   124  {
   125      if (fileName.isEmpty()) {
   126          qCWarning(KArchiveLog) << "KArchive: No file name specified";
   127      }
   128      d->fileName = fileName;
   129      // This constructor leaves the device set to 0.
   130      // This is for the use of QSaveFile, see open().
   131  }
