   133  KArchive::KArchive(QIODevice *dev)
   134      : d(new KArchivePrivate(this))
   135  {
   136      if (!dev) {
   137          qCWarning(KArchiveLog) << "KArchive: Null device specified";
   138      }
   139      d->dev = dev;
   140  }
