   181  bool KArchive::createDevice(QIODevice::OpenMode mode)
   182  {
   183      switch (mode) {
   184      case QIODevice::WriteOnly:
   185          if (!d->fileName.isEmpty()) {
   186              // The use of QSaveFile can't be done in the ctor (no mode known yet)
   187              //qCDebug(KArchiveLog) << "Writing to a file using QSaveFile";
   188              d->saveFile = new QSaveFile(d->fileName);
   189              if (!d->saveFile->open(QIODevice::WriteOnly)) {
   190                  setErrorString(
   191                      tr("QSaveFile creation for %1 failed: %2")
   192                          .arg(d->fileName, d->saveFile->errorString()));
   193
   194                  delete d->saveFile;
   195                  d->saveFile = nullptr;
   196                  return false;
   197              }
   198              d->dev = d->saveFile;
   199              Q_ASSERT(d->dev);
   200          }
   201          break;
   202      case QIODevice::ReadOnly:
   203      case QIODevice::ReadWrite:
   204          // ReadWrite mode still uses QFile for now; we'd need to copy to the tempfile, in fact.
   205          if (!d->fileName.isEmpty()) {
   206              d->dev = new QFile(d->fileName);
   207              d->deviceOwned = true;
   208          }
   209          break; // continued below
   210      default:
   211          setErrorString(tr("Unsupported mode %1").arg(d->mode));
   212          return false;
   213      }
   214      return true;
   215  }
