   217  bool KArchive::close()
   218  {
   219      if (!isOpen()) {
   220          setErrorString(tr("Archive already closed"));
   221          return false;    // already closed (return false or true? arguable...)
   222      }
   223
   224      // moved by holger to allow kzip to write the zip central dir
   225      // to the file in closeArchive()
   226      // DF: added d->dev so that we skip closeArchive if saving aborted.
   227      bool closeSucceeded = true;
   228      if (d->dev) {
   229          closeSucceeded = closeArchive();
   230          if (d->mode == QIODevice::WriteOnly && !closeSucceeded) {
   231              d->abortWriting();
   232          }
   233      }
   234
   235      if (d->dev && d->dev != d->saveFile) {
   236          d->dev->close();
   237      }
   238
   239      // if d->saveFile is not null then it is equal to d->dev.
   240      if (d->saveFile) {
   241          closeSucceeded = d->saveFile->commit();
   242          delete d->saveFile;
   243          d->saveFile = nullptr;
   244      }
   245      if (d->deviceOwned) {
   246          delete d->dev; // we created it ourselves in open()
   247      }
   248
   249      delete d->rootDir;
   250      d->rootDir = nullptr;
   360      Q_ASSERT(file->openMode() & QIODevice::ReadOnly);
   361
   362      //qCDebug(KArchiveLog) << "filling tmpFile finished.";
   363      return true;
   364  }
