   366  bool KTar::openArchive(QIODevice::OpenMode mode)
   367  {
   368
   369      if (!(mode & QIODevice::ReadOnly)) {
   370          return true;
   371      }
   372
   373      if (!d->fillTempFile(fileName())) {
   374          return false;
   375      }
   376
   377      // We'll use the permission and user/group of d->rootDir
   378      // for any directory we emulate (see findOrCreate)
   379      //struct stat buf;
   380      //stat( fileName(), &buf );
   381
   382      d->dirList.clear();
   383      QIODevice *dev = device();
   384
   385      if (!dev) {
   386          setErrorString(tr("Could not get underlying device"));
   387          qCWarning(KArchiveLog) << "Could not get underlying device";
   388          return false;
   389      }
   390
   391      // read dir information
   392      char buffer[0x200];
   393      bool ende = false;
   394      do {
   395          QString name;
   396          QString symlink;
   397
   398          // Read header
   399          qint64 n = d->readHeader(buffer, name, symlink);
   400          if (n < 0) {
   401              setErrorString(tr("Could not read tar header"));
   402              return false;
   403          }
   404          if (n == 0x200) {
   405              bool isdir = false;
   406
   407              if (name.isEmpty()) {
   408                  continue;
   409              }
   410              if (name.endsWith(QLatin1Char('/'))) {
   411                  isdir = true;
   412                  name.truncate(name.length() - 1);
   413              }
   414
   415              QByteArray prefix = QByteArray(buffer + 0x159, 155);
   416              if (prefix[0] != '\0') {
   417                  name = (QString::fromLatin1(prefix.constData()) + QLatin1Char('/') +  name);
   418              }
   419
   420              int pos = name.lastIndexOf(QLatin1Char('/'));
   421              QString nm = (pos == -1) ? name : name.mid(pos + 1);
   422
   423              // read access
   424              buffer[0x6b] = 0;
   425              char *dummy;
   426              const char *p = buffer + 0x64;
   427              while (*p == ' ') {
   428                  ++p;
   429              }
   430              int access = strtol(p, &dummy, 8);
   431
   432              // read user and group
   433              const int maxUserGroupLength = 32;
   434              const char *userStart = buffer + 0x109;
   435              const int userLen = qstrnlen(userStart, maxUserGroupLength);
   436              const QString user = QString::fromLocal8Bit(userStart, userLen);
   437              const char *groupStart = buffer + 0x129;
   438              const int groupLen = qstrnlen(groupStart, maxUserGroupLength);
   439              const QString group = QString::fromLocal8Bit(groupStart, groupLen);
   440
   441              // read time
   442              buffer[0x93] = 0;
   443              p = buffer + 0x88;
   444              while (*p == ' ') {
   445                  ++p;
   446              }
   447              uint time = strtol(p, &dummy, 8);
   448
   449              // read type flag
   450              char typeflag = buffer[0x9c];
   451              // '0' for files, '1' hard link, '2' symlink, '5' for directory
   452              // (and 'L' for longlink fileNames, 'K' for longlink symlink targets)
   453              // 'D' for GNU tar extension DUMPDIR, 'x' for Extended header referring
   454              // to the next file in the archive and 'g' for Global extended header
   455
   456              if (typeflag == '5') {
   457                  isdir = true;
   458              }
   459
   460              bool isDumpDir = false;
